using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "MultiphaseEffect", menuName = "Data/Battle/Effects/Sentinel/MultiphaseEffect")]
public class MultiphaseEffect : Effect
{
	[Header("State Changer")]
	[SerializeField]
	private int purifyAmountToChange = 3;

	[SerializeField]
	private int corruptAmountToChange = 2;

	[SerializeField]
	private CompanionData stateOneCompanionData;

	[SerializeField]
	private CompanionData stateTwoCompanionData;

	[SerializeField]
	private CompanionsListsList companionsListsList;

	[SerializeField]
	private Sprite purifiedPhaseIcon;

	[SerializeField]
	private Sprite corruptedPhaseIcon;

	[NonSerialized]
	private bool stateOne;

	[NonSerialized]
	private bool changingSentinelState;

	public void SetStateOneCompanionAnimalData(CompanionData stateOneCompanionData)
	{
		this.stateOneCompanionData = stateOneCompanionData;
	}

	public void SetStateTwoCompanionAnimalData(CompanionData stateTwoCompanionData)
	{
		this.stateTwoCompanionData = stateTwoCompanionData;
	}

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		string localizedString = base.localizationManager.GetLocalizedString(stateOne ? "PurifiedPhase" : "CorruptedPhase");
		return Smart.Format(localizedDescription, localizedString, corruptAmountToChange, purifyAmountToChange);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		if (GameScenesUtils.IsMainMenu())
		{
			if (effectOwner.TryGetComponent<CompanionInitializer>(out var component2))
			{
				string companionID = component2.CompanionData.CompanionID;
				if (companionID == "MultiphaseGear")
				{
					stateOne = true;
					component.IsEffectActiveGetEffectInstance(this).SetImage(purifiedPhaseIcon);
				}
				else if (companionID == "MultiphaseGearTwo")
				{
					stateOne = false;
					component.IsEffectActiveGetEffectInstance(this).SetImage(corruptedPhaseIcon);
				}
			}
		}
		else
		{
			changingSentinelState = false;
			stateOne = true;
		}
	}

	public override void InitializeCompendium(int effectAmount, GameObject effectOwner)
	{
		Initialize(effectAmount, effectOwner, null);
	}

	public override int ActivateEffectWithPurifyAmountAndSource(int effectAmount, GameObject effectOwner, int purifyAmount, GameObject source)
	{
		if (!stateOne && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && purifyAmount >= purifyAmountToChange)
		{
			ChangeSentinelState(effectOwner);
		}
		return effectAmount;
	}

	public override int ActivateEffectWithCorruptAmountAndSource(int effectAmount, GameObject effectOwner, int corruptAmount, GameObject source)
	{
		if (stateOne && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && corruptAmount >= corruptAmountToChange)
		{
			ChangeSentinelState(effectOwner);
		}
		return effectAmount;
	}

	private void ChangeSentinelState(GameObject effectOwner)
	{
		if (!changingSentinelState)
		{
			GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
			UnitEffects component = effectOwner.GetComponent<UnitEffects>();
			changingSentinelState = true;
			instance.ActionsQueueState.EnqueueAfterAction(ChangeSentinelState(effectOwner, component));
			instance.SetActionsQueueState();
		}
	}

	private IEnumerator ChangeSentinelState(GameObject effectOwner, UnitEffects unitEffects)
	{
		yield return InvokeAlternatives.WaitForFrames(3);
		if (!effectOwner.activeInHierarchy)
		{
			yield break;
		}
		CompanionAbility component = effectOwner.GetComponent<CompanionAbility>();
		CompanionInitializer component2 = effectOwner.GetComponent<CompanionInitializer>();
		SpriteControl spriteControl = effectOwner.GetComponent<SpriteControl>();
		CompanionDice companionDice = stateOneCompanionData.CompanionLevels[component2.CompanionLevel].CompanionDice;
		CompanionDice companionDice2 = stateTwoCompanionData.CompanionLevels[component2.CompanionLevel].CompanionDice;
		Dice defaultDice;
		if (stateOne)
		{
			defaultDice = companionDice2;
			unitEffects.IsEffectActive(this);
			spriteControl.PlayAnimationForced(AnimationType.Skill, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
			{
				spriteControl.PlayAnimationForced(AnimationType.Idle2, AnimationChangeType.StayInTheNewAnimationLooping);
				unitEffects.IsEffectActiveGetEffectInstance(this).SetImage(corruptedPhaseIcon);
				unitEffects.IsEffectActive(this);
			});
			if (stateTwoCompanionData.CompendiumItemState == CompendiumItemState.Undiscovered)
			{
				List<CompanionData> companionDatas = new List<CompanionData> { stateTwoCompanionData };
				companionsListsList.SentinelsDiscovered(companionDatas);
			}
		}
		else
		{
			defaultDice = companionDice;
			unitEffects.IsEffectActive(this);
			spriteControl.PlayAnimationForced(AnimationType.Skill2, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
			{
				spriteControl.PlayAnimationForced(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
				unitEffects.IsEffectActiveGetEffectInstance(this).SetImage(purifiedPhaseIcon);
				unitEffects.IsEffectActive(this);
			});
		}
		List<DiceInstance> diceInstancesToRoll = component.GetDiceInstancesToRoll();
		component.InitializeWithoutStoreDiceWithoutResettingEmpowerAndHideDiceface(defaultDice);
		component.UpdateActionValueModifier();
		component.UpdateDiceInstances();
		diceInstancesToRoll.RemoveAll((DiceInstance item) => item.DiceState == DiceState.Rolling);
		if (diceInstancesToRoll.Count > 0)
		{
			ReferenceSingleton<AssetsReference>.Instance.RerollAction.ExternalCast(diceInstancesToRoll, RollDiceActionType.REARM, null);
		}
		stateOne = !stateOne;
		yield return InvokeAlternatives.WaitForFrames(3);
		changingSentinelState = false;
	}
}
